#!/usr/bin/env bash
# Enforces `type(scope)?: subject` and forbids AI co-author trailers.
set -euo pipefail

msg_file="$1"
subject="$(head -n1 "$msg_file")"
types="feat|fix|chore|refactor|docs|test|ci|perf|build|revert"

# Merge, fixup and revert commits generated by git are allowed as-is.
if [[ "$subject" =~ ^(Merge|Revert|fixup!|squash!) ]]; then
  exit 0
fi

if ! [[ "$subject" =~ ^($types)(\([a-z0-9._/-]+\))?!?:\ .+ ]]; then
  echo "✖ Commit subject must look like 'feat: add x' or 'fix(api): handle y'."
  echo "  Allowed types: ${types//|/, }"
  echo "  Got: $subject"
  exit 1
fi

if (( ${#subject} > 72 )); then
  echo "✖ Commit subject is ${#subject} chars; keep it within 72."
  exit 1
fi

if grep -qiE '^co-authored-by:.*(claude|anthropic)|generated with \[?claude' "$msg_file"; then
  echo "✖ Remove AI attribution lines from the commit message."
  exit 1
fi
